/**
 * Buildium credential management.
 *
 * Mirrors the backend `/api/v1/buildium/*` surface. The webhook signing
 * secret is generated by Buildium (Settings → Developer Tools →
 * Webhooks → Add Webhook → Generate key) and pasted into Occupella by
 * the user — Occupella never generates it. Read-side `getStatus` returns
 * masked metadata only; plaintext never round-trips through the API.
 *
 * Demo mode short-circuits so the connectors page stays connected
 * regardless of backend state during the demo.
 */

import { apiFetch } from './api';
import { demoMode } from './auth';
import { backendOrigin } from './backendOrigin';

export type BuildiumEnvironment = 'sandbox' | 'production';

export interface BuildiumStatus {
  configured: boolean;
  client_id_last4: string | null;
  webhook_secret_last4: string | null;
  environment: BuildiumEnvironment | null;
  last_tested_at: string | null;
  test_account_name: string | null;
  test_properties_count: number | null;
}

export interface BuildiumCredentialsInput {
  client_id: string;
  client_secret: string;
  environment: BuildiumEnvironment;
}

export interface BuildiumTestResult {
  ok: boolean;
  account_name: string | null;
  properties_count: number | null;
  error: string | null;
}

export interface BuildiumEvent {
  id: string;
  event_name: string;
  event_time: string;
  status: 'pending' | 'running' | 'done' | 'failed';
  last_error: string | null;
}

