/** Initial-sync progress for the caller's company (GET /buildium/sync-status).
 *
 * `stale` is DERIVED server-side: `run_initial_sync` is fire-and-forget, so a
 * process killed mid-crawl (a deploy) leaves the row at 'syncing' forever. The
 * backend reports "hasn't progressed" rather than asserting failure, because it
 * cannot tell a dead crawl from a slow one.
 */
export type SyncStatusValue = 'unknown' | 'pending' | 'syncing' | 'done' | 'failed';

export interface SyncStatus {
  status: SyncStatusValue;
  counts: Record<string, number>;
  started_at: string | null;
  finished_at: string | null;
  last_error: string | null;
  stale: boolean;
}

export async function fetchSyncStatus(): Promise<SyncStatus> {
  if (demoMode) {
    return {
      status: 'done',
      counts: {},
      started_at: null,
      finished_at: null,
      last_error: null,
      stale: false,
    };
  }
  const res = await apiFetch('/api/v1/buildium/sync-status');
  return res.json();
}

export async function getBuildiumStatus(): Promise<BuildiumStatus> {
  if (demoMode) return DEMO_STATUS;
  const res = await apiFetch('/api/v1/buildium/credentials');
  return res.json();
}

export async function saveBuildiumCreds(
  input: BuildiumCredentialsInput,
): Promise<BuildiumStatus> {
  if (demoMode) {
    await new Promise((r) => setTimeout(r, 400));
    return {
      ...DEMO_STATUS,
      client_id_last4: input.client_id.slice(-4),
      environment: input.environment,
      last_tested_at: null,
      test_account_name: null,
      test_properties_count: null,
    };
  }
  const res = await apiFetch('/api/v1/buildium/credentials', {
    method: 'PUT',
    body: JSON.stringify(input),
  });
  return res.json();
}

export async function deleteBuildiumCreds(): Promise<BuildiumStatus> {
  if (demoMode) {
    return {
      configured: false,
      client_id_last4: null,
      webhook_secret_last4: null,
      environment: null,
      last_tested_at: null,
      test_account_name: null,
      test_properties_count: null,
    };
  }
  const res = await apiFetch('/api/v1/buildium/credentials', { method: 'DELETE' });
  return res.json();
}

export async function testBuildiumConnection(): Promise<BuildiumTestResult> {
  if (demoMode) {
    await new Promise((r) => setTimeout(r, 700));
    return { ok: true, account_name: 'occupella-demo', properties_count: 14, error: null };
  }
  const res = await apiFetch('/api/v1/buildium/test', { method: 'POST' });
  return res.json();
}

export interface BuildiumBackfillResult {
  ok: boolean;
  properties: number;
  units: number;
  tenants: number;
  leases: number;
  balances: number;
  transactions: number;
  work_orders?: number;
  applicants?: number;
  vendors?: number;
  owners?: number;
  tasks?: number;
  gl_accounts?: number;
  bills?: number;
  bank_accounts?: number;
  errors: string[];
  error?: string | null;
}

/**
 * Pull the whole Buildium account into the local entity mirror (the
 * cockpit's data source). Idempotent — re-running upserts. Requires a
 * successful connection test first (that stores the account_id).
 */
export async function runBuildiumBackfill(): Promise<BuildiumBackfillResult> {
  if (demoMode) {
    await new Promise((r) => setTimeout(r, 900));
    return {
      ok: true,
      properties: 14,
      units: 38,
      tenants: 41,
      leases: 35,
      balances: 3,
      transactions: 62,
      work_orders: 6,
      applicants: 4,
      vendors: 9,
      owners: 5,
      tasks: 12,
      gl_accounts: 40,
      bills: 7,
      bank_accounts: 3,
      errors: [],
    };
  }
  const res = await apiFetch('/api/v1/buildium/backfill', { method: 'POST' });
  return res.json();
}

/**
 * Save the signing secret Buildium showed the user when they created
 * the webhook subscription. Resolves on success; throws on validation /
 * server error so the panel can surface it.
 */
export async function setWebhookSecret(secret: string): Promise<void> {
  if (demoMode) {
    await new Promise((r) => setTimeout(r, 350));
    return;
  }
  const res = await apiFetch('/api/v1/buildium/webhook-secret', {
    method: 'PUT',
    body: JSON.stringify({ secret }),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(text || `Failed to save secret (${res.status})`);
  }
}

/**
 * Forget the stored secret. Webhooks will start failing until the user
 * pastes a new one. Confirm before calling — this is destructive.
 */
export async function deleteWebhookSecret(): Promise<void> {
  if (demoMode) {
    await new Promise((r) => setTimeout(r, 200));
    return;
  }
  const res = await apiFetch('/api/v1/buildium/webhook-secret', {
    method: 'DELETE',
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(text || `Failed to delete secret (${res.status})`);
  }
}

export async function getRecentBuildiumEvents(): Promise<BuildiumEvent[]> {
  if (demoMode) return DEMO_EVENTS;
  const res = await apiFetch('/api/v1/buildium/recent-events');
  return res.json();
}

/** The webhook URL Buildium should POST to. Built from the page origin
 *  so dev / preview / prod all route correctly without a separate env var. */
export function buildiumWebhookUrl(): string {
  if (typeof window === 'undefined') return '/webhooks/buildium';
  // Buildium POSTs straight to the Render host: vercel.json rewrites /api/*
  // only, not /webhooks/*.
  return `${backendOrigin()}/webhooks/buildium`;
}

